function publicDiscovery(){
 const publicHome=!!$('#free-apps'),catalog=!!$('#app-results');
 document.body.classList.toggle('has-app-finder',publicHome||catalog);
 document.body.classList.toggle('finder-workspace',catalog);
 if(!publicHome&&!catalog){$('#app-finder-trigger')?.remove();$('#app-finder-dialog')?.close();return;}
 if($('#app-finder-trigger'))return;
 const trigger=document.createElement('button');trigger.id='app-finder-trigger';trigger.className='app-finder-trigger';trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls','app-finder-dialog');trigger.innerHTML=icon('search')+'<span>Search apps</span>';trigger.onclick=openAppFinder;($('#free-apps .access-heading')||document.body).append(trigger);
}
function finderApps(){
 if(state)return state.apps.filter(a=>!a.catalogueParent).map(a=>({...a,keywords:publicKeywords[a.path]||'',purpose:publicPurposes[a.path]||'Work'}));
 return [...document.querySelectorAll('#free-apps .public-app')].map(card=>{const path=new URL(card.href).pathname;return {name:card.getAttribute('aria-label').replace(/^Open /,''),description:card.querySelector('.public-app-copy p')?.textContent||'',path,keywords:publicKeywords[path]||'',purpose:publicPurposes[path],icon:path==='/fund-overlap'?'lens':path==='/news'?'knowledge':'star',accessible:true,public:true,status:'Available'};});
}
function openAppFinder(){
 let modal=$('#app-finder-dialog');if(!modal){modal=document.createElement('dialog');modal.id='app-finder-dialog';modal.className='app-finder-dialog';modal.setAttribute('aria-labelledby','finder-title');document.body.append(modal);modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();modal.close();}});modal.addEventListener('close',()=>{document.body.classList.remove('finder-open');if(modal.savedScroll)scrollTo(modal.savedScroll.x,modal.savedScroll.y);$('#app-finder-trigger')?.focus({preventScroll:true});});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});}
 const apps=finderApps(),purposes=['All',...new Set(apps.map(a=>a.purpose))];let purpose='All';
 modal.innerHTML=`<div class="finder-heading"><div><span class="eyebrow">A TOOL FOR YOUR MOMENT</span><h2 id="finder-title">What do you need?</h2></div><button class="finder-close" aria-label="Close app search">×</button></div><label class="finder-input">${icon('search')}<input id="finder-search" type="search" aria-label="Search apps or activities" placeholder="Search apps or activities" autocomplete="off"><button class="finder-clear" aria-label="Clear search" hidden>×</button></label><div class="finder-purposes" aria-label="Filter apps by purpose">${purposes.map(p=>`<button data-purpose="${p}" aria-pressed="${p==='All'}">${escapeHtml(p)}</button>`).join('')}</div><p id="finder-count" role="status" aria-live="polite"></p><div class="finder-results"></div>`;
 const input=modal.querySelector('input'),clear=modal.querySelector('.finder-clear');
 const filter=()=>{const terms=input.value.trim().toLowerCase().split(/\s+/).filter(Boolean),matches=apps.filter(a=>(purpose==='All'||a.purpose===purpose)&&terms.every(term=>[a.name,a.description,a.keywords,a.purpose].join(' ').toLowerCase().includes(term)));clear.hidden=!input.value;modal.querySelector('#finder-count').textContent=matches.length?`${matches.length} app${matches.length===1?'':'s'} · ${state?'Your platform collection':'Free to use, no sign-in needed'}`:'No matching apps. Try a different word or choose All.';modal.querySelector('.finder-results').innerHTML=matches.map(a=>{const inner=`<span class="finder-glyph">${sculpture(a,'finder-sculpture')}</span><span class="finder-copy"><strong>${escapeHtml(a.name)}</strong><small>${escapeHtml(a.description)}</small><em>${a.status==='Planned'?'Planned · not available':!a.accessible?'Access required · contact your owner':a.public?'Free · no sign-in':a.ownerOnly?'Owner account only':'Your workspace'}</em></span>${icon(a.accessible?'arrow':'lock')}`;return a.accessible&&a.status!=='Planned'?(state?`<button class="finder-result" data-action="launch" data-id="${escapeHtml(a.id)}">${inner}</button>`:`<a class="finder-result" href="${escapeHtml(a.path)}">${inner}</a>`):`<div class="finder-result finder-unavailable">${inner}</div>`;}).join('');};
 input.oninput=filter;clear.onclick=()=>{input.value='';filter();input.focus();};modal.querySelector('.finder-close').onclick=()=>modal.close();modal.querySelectorAll('[data-purpose]').forEach(button=>button.onclick=()=>{purpose=button.dataset.purpose;modal.querySelectorAll('[data-purpose]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filter();});filter();modal.savedScroll={x:scrollX,y:scrollY};document.body.classList.add('finder-open');modal.showModal();input.focus();
}
