let theme=SynapseTheme.read();
const systemTheme=matchMedia('(prefers-color-scheme: dark)');
function setTheme(value){theme=value;SynapseTheme.write(value);document.documentElement.dataset.theme=theme==='system'?(systemTheme.matches?'dark':'light'):theme;document.querySelectorAll('[data-theme-icon]').forEach(el=>el.innerHTML=icon(document.documentElement.dataset.theme==='dark'?'moon':'sun'));}
setTheme(theme);systemTheme.addEventListener('change',()=>setTheme(theme));
function themeControl(){return SynapseTheme.control('data-theme');}
function brand(){return `<a class="brand" href="/" aria-label="Sushant Synapse home"><img src="/logo-adaptive-192.png" alt="" width="42" height="42"><span>Sushant Synapse<small>PLATFORM</small></span></a>`;}
function notice(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').classList.remove('show'),3500);}
async function api(route,method='GET',body){const r=await fetch('/api/'+route,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&state){state=null;section='apps';category='All';query='';await boot();}throw Error(data.error||'Request failed');}return data;}
async function submit(form,fn){const button=form.querySelector('[type="submit"]');button.disabled=true;form.querySelector('.error').textContent='';try{await fn();}catch(e){form.querySelector('.error').textContent=e.message;}finally{button.disabled=false;}}
const privateDestinations={'digital-samaj':{path:'/digital-samaj',name:'DIGITAL SAMAJ'},'advocate':{path:'/advocate',name:'Chambers'},'tournament-lite':{path:'/tournament-lite',name:'Tournament Lite'},'batchfee-lite':{path:'/batchfee-lite',name:'BatchFee Lite'}};
function requestedApp(){const id=new URLSearchParams(location.search).get('next');return Object.hasOwn(privateDestinations,id)?privateDestinations[id]:null;}
function authView(){if(authStatus.authMethod==='access'){freeAuthView();return;}const setup=authStatus.setupRequired,target=requestedApp();$('#platform').innerHTML=`<main id="main" class="auth-layout"><section class="welcome">${brand()}<div class="welcome-copy"><span class="eyebrow">YOUR PRIVATE WORKSPACE</span><h1>Your work.<br><em>In good order.</em></h1><p>Sign in for Chambers, tournament organizing and your assigned apps. BatchFee Lite is reserved for the platform owner.</p><div class="welcome-app"><span class="app-icon green">${icon('scales')}</span><div><strong>Access that fits your work</strong><small>Your platform owner manages accounts and app access.</small></div>${icon('arrow')}</div></div><span class="welcome-footer">apps.sushantsynapse.com</span></section><section class="auth-panel"><div class="auth-theme">${themeControl()}</div><form id="auth-form"><span class="eyebrow">${setup?'LET’S GET STARTED':'YOUR APPS ARE WAITING'}</span><h2>${setup?'Set up your platform':'Welcome back'}</h2><p>${setup?'Create your owner account. Existing Chambers records will stay right where they are.':(target?'Continue to '+target.name+' with your platform account.':'Sign in to open your private workspace and assigned apps.')}</p>${setup?'<label>Your name<input name="name" required autocomplete="name" maxlength="120"></label><label>Workspace name<input name="firmName" required placeholder="Your organisation or chambers" maxlength="200"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required minlength="${setup?'12':'1'}" maxlength="128" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<p class="hint">Use at least 12 characters.</p>':''}${setup&&authStatus.setupProtected?'<label>Setup token<input name="setupToken" type="password" required autocomplete="off"><small>Provided by the person deploying this platform.</small></label>':''}<p class="error" role="alert"></p><button class="primary wide" type="submit">${setup?'Create platform':'Sign in'} ${icon('arrow')}</button><p class="auth-note">${setup?'Add team members and choose their app access after setup.':'Need an account or a password reset? Contact your platform owner.'}</p></form><nav class="auth-public" aria-label="Public apps"><span class="eyebrow">JUST EXPLORING?</span><h3>Free to try, without signing in</h3><div class="auth-public-links"><a href="/take-a-break">Take a Break ↗</a><a href="/team-mixer">Team Mixer &#8599;</a><a href="/ritual-assist">Ritual Assist ↗</a><a href="/moment-studio">Moment Studio &#8599;</a><a href="/timetable-lite">Timetable Lite ↗</a><a href="/fund-overlap">Fund Lens ↗</a><a href="/news">Sushant Synapse Times ↗</a></div><a class="back-home" href="/">← Back to all apps</a></nav><div class="secure-note">${icon('lock')} One account across Sushant Synapse apps</div></section></main>`;$('#auth-form').onsubmit=e=>{e.preventDefault();submit(e.target,async()=>{await api(setup?'auth/setup':'auth/login','POST',Object.fromEntries(new FormData(e.target)));if(target){location.assign(target.path);return;}history.replaceState(null,'','/');await load();});};}
const navItems=[['apps','grid','All apps'],['favorites','star','Favourites'],['recent','clock','Recent'],['team','team','Team access'],['profile','user','My profile']];
function nav(){return navItems.filter(([id])=>id!=='team'||state.user.role==='Owner').map(([id,glyph,name])=>`<button data-section="${id}" class="nav-item ${section===id?'selected':''}" ${section===id?'aria-current="page"':''}>${icon(glyph)}<span>${name}</span></button>`).join('');}
function normalizeStudioCatalogue(){if(state.apps.some(a=>a.id==='moment-studio'))return;const legacy=state.apps.find(a=>a.id==='certificates')||state.apps.find(a=>a.id==='celebration-studio');if(!legacy)return;const merged={...legacy,name:'Moment Studio',subtitle:'Words for every kind of moment.',path:'/moment-studio',icon:'star',description:'Certificates, celebrations and thoughtful condolences in one branded creative app.',features:['Cards & certificates','Condolence wording','Branded exports'],studioLegacy:true};state.apps=state.apps.filter(a=>!['certificates','celebration-studio'].includes(a.id));state.apps.unshift(merged);const alias=id=>['certificates','celebration-studio'].includes(id)?legacy.id:id;state.preferences.favorites=[...new Set(state.preferences.favorites.map(alias))];state.preferences.recent=state.preferences.recent.map(r=>({...r,id:alias(r.id)})).filter((r,i,all)=>all.findIndex(v=>v.id===r.id)===i);}
function normalizeBreakCatalogue(){const hub=state.apps.find(a=>a.id==='daily-spark');if(!hub)return;Object.assign(hub,{name:'Take a Break',path:'/take-a-break',category:'Play',subtitle:'Eight ways to reset.',description:'One-Minute Chaos, Make 24, Crack the Code, Memory Minute, Lights Out, Face-Off, Decision Wheel and Pocket Pause in one free play hub.',features:['Daily & practice games','Choose or unwind','Challenge a friend']});state.apps.filter(a=>a.id==='pocket-pause').forEach(a=>a.catalogueParent='daily-spark');const wheel=state.apps.find(a=>a.id==='decision-wheel');if(wheel)delete wheel.catalogueParent;}
async function load(){state=await api('platform');normalizeStudioCatalogue();normalizeBreakCatalogue();const first=['/moment-studio','/take-a-break','/decision-wheel','/news'];state.apps.sort((a,b)=>(first.includes(a.path)?first.indexOf(a.path):first.length)-(first.includes(b.path)?first.indexOf(b.path):first.length));if(section==='team'&&state.user.role!=='Owner')section='apps';render();}
function render(){window.dispatchEvent(new CustomEvent('synapse-auth-change',{detail:{user:state.user}}));const count=state.apps.filter(a=>a.accessible&&!a.catalogueParent).length;$('#platform').innerHTML=`<aside class="sidebar"><a class="brand" href="/">Your workspace</a><span class="nav-caption">YOUR WORKSPACE</span><nav aria-label="Platform navigation">${nav()}</nav><div class="sidebar-bottom"><div class="platform-note"><span class="dot"></span> Built to grow with you<p>One home for everything<br>you do next.</p></div><div class="account"><span class="avatar">${escapeHtml(initials(state.user.name))}</span><div><strong>${escapeHtml(state.user.name)}</strong><small>${escapeHtml(state.user.role)}</small></div><button class="icon-button" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar synapse-header"><a class="brand" href="/" aria-label="Sushant Synapse home"><img src="/logo-adaptive-192.png" width="42" height="42" alt=""><span>Sushant Synapse<small>PLATFORM</small></span></a><div class="header-actions">${themeControl()}<button class="avatar profile-button" data-section="profile" aria-label="My profile">${escapeHtml(initials(state.user.name))}</button></div></header><nav class="synapse-help-nav" aria-label="Support and contact"><a href="/satire-arena">Satire Arena</a><a href="/support">Support us</a><a href="/showcase">Watch demos</a><a href="/contact">Contact</a><a href="https://wa.me/917874166009?text=Hello%2C%20I%20would%20like%20to%20contact%20Sushant%20Synapse." target="_blank" rel="noopener noreferrer">WhatsApp ↗</a></nav><main id="main"><div class="page-top"><div><span class="eyebrow">SUSHANT SYNAPSE PLATFORM</span><h1>${section==='apps'?`Welcome, ${escapeHtml(state.user.name.split(' ')[0])}.`:section==='favorites'?'Your favourites.':section==='recent'?'Pick up where you left off.':section==='team'?'The right apps. The right people.':'Make yourself at home.'}</h1><p>${section==='apps'?'One home for your apps. More room for what matters.':section==='favorites'?'Keep your everyday apps close at hand.':section==='recent'?'Your recently opened apps, ready when you are.':section==='team'?'Manage accounts and access to each available app.':'Your account is shared across all Sushant Synapse apps.'}</p></div>${section==='apps'?`<span class="available-count"><span class="dot"></span>${count} app${count===1?'':'s'} available to you</span>`:''}</div><div id="content">${content()}</div><footer><span>Sushant Synapse Platform</span><span><a href="/showcase">Watch demos</a> · <a href="/support">Support us</a></span></footer></main></div><nav class="mobile-nav" aria-label="Mobile platform navigation">${nav()}</nav>`;bindForms();}
function content(){if(section==='team')return teamView();if(section==='profile')return profileView();const list=filteredApps();return `${section==='apps'?`<section class="intro-banner"><div><span class="eyebrow">YOUR APP COLLECTION</span><h2>Your tools. Ready for work.</h2><p>Open a workspace, pick up a recent task or keep your everyday tools in favourites.</p></div><div class="collection-art" aria-hidden="true">${sculpture({id:'advocate'})}${sculpture({id:'digital-samaj'})}${sculpture({id:'tournament-lite'})}</div></section>`:''}<div class="catalog-toolbar"><div class="tabs" aria-label="App categories">${['All',...new Set(state.apps.map(a=>a.category))].map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div></div><div id="app-results">${appGrid(list)}</div>${section==='apps'?'<p class="catalog-note">Planned apps are a preview of the roadmap. They are not available to open yet.</p>':''}`;}
function filteredApps(){let list=section==='apps'?state.apps.filter(a=>!a.catalogueParent):state.apps;if(section==='favorites')list=list.filter(a=>state.preferences.favorites.includes(a.id));if(section==='recent')list=state.preferences.recent.map(r=>state.apps.find(a=>a.id===r.id)).filter(Boolean);return list.filter(a=>(category==='All'||a.category===category)&&[a.name,a.subtitle,a.category,a.description].join(' ').toLowerCase().includes(query.toLowerCase()));}
function appGrid(list){return list.length?`<div class="app-grid">${list.map(a=>`<article data-app-id="${escapeHtml(a.id)}" class="app-card ${a.status==='Planned'?'planned':''}"><div class="app-card-top"><span class="app-art-wrap">${sculpture(a)}</span><span class="badge ${a.accessible?'available':''}">${a.status==='Planned'?'Planned':a.status==='Unavailable'?'Unavailable':a.accessible?'Available':'Access required'}</span>${a.accessible&&a.status!=='Planned'?`<button class="icon-button favorite ${state.preferences.favorites.includes(a.id)?'saved':''}" data-action="favorite" data-id="${a.id}" aria-label="${state.preferences.favorites.includes(a.id)?'Remove '+a.name+' from favourites':'Add '+a.name+' to favourites'}" aria-pressed="${state.preferences.favorites.includes(a.id)}">${icon('star')}</button>`:''}</div><span class="app-category">${a.category}</span>${a.status==='Available'?`<span class="access-label ${a.public?'':'private'}">${a.public?'No sign-in required':a.ownerOnly?'Owner account only':'Sign-in + app access'}</span>`:''}<h2>${a.name}</h2><h3>${a.subtitle}</h3><p>${a.description}</p><div class="feature-tags">${a.features.map(f=>`<span>${f}</span>`).join('')}</div><div class="app-card-bottom">${a.accessible&&a.status!=='Planned'?`<button class="launch" data-action="launch" data-id="${a.id}">Open ${a.name} ${icon('arrow')}</button>`:a.status==='Planned'?`<span class="not-live">${icon('clock')} In the pipeline</span>`:`<span class="not-live">${icon('lock')} Contact your platform owner</span>`}${section==='recent'?`<small>${new Date(state.preferences.recent.find(r=>r.id===a.id).at).toLocaleDateString('en-IN')}</small>`:''}</div></article>`).join('')}</div>`:`<div class="empty">${icon(section==='favorites'?'star':'search')}<h2>${section==='favorites'&&!query?'No favourites yet':'No apps to show'}</h2><p>${section==='favorites'?'Use the star on an available app to save it here.':section==='recent'?'Apps you open from this platform will appear here.':'Try another category or search term.'}</p><button class="secondary" data-section="apps">Browse all apps</button></div>`;}
function profileView(){if(authStatus.authMethod==='access')return freeProfileView();return `<div class="settings-grid"><section class="panel"><h2>Your profile</h2><p>This identity appears across your apps.</p><form id="profile-form"><label>Name<input name="name" value="${escapeHtml(state.user.name)}" required maxlength="120"></label><label>Email<input name="email" type="email" value="${escapeHtml(state.user.email)}" required></label><p class="error" role="alert"></p><button type="submit" class="primary">Save profile</button></form></section><section class="panel"><h2>Password & security</h2><p>Changing your password signs out other sessions.</p><form id="password-form"><label>Current password<input type="password" name="currentPassword" required autocomplete="current-password"></label><label>New password<input type="password" name="newPassword" minlength="12" maxlength="128" required autocomplete="new-password"></label><p class="error" role="alert"></p><button type="submit" class="secondary">Change password</button></form></section><section class="panel"><h2>Appearance</h2><p>Your theme follows you between Synapse and Chambers on this device.</p>${themeControl()}<button class="secondary signout" data-action="logout">${icon('logout')} Sign out</button></section></div>`;}
function teamView(){return `<section class="panel team-panel"><div class="section-heading"><div><h2>Platform accounts</h2><p>Owners can open every available app. Other users receive access individually. Advocate and clerk permissions apply inside Chambers.</p></div><button class="primary" data-action="add-user">${icon('plus')} Add member</button></div>${state.team.map(u=>`<article class="team-row"><span class="avatar">${escapeHtml(initials(u.name))}</span><div class="team-person"><strong>${escapeHtml(u.name)}</strong><small>${escapeHtml(u.email)}</small><span class="role-label">${u.role}${u.active?'':' · Inactive'}</span></div><div class="access-list">${state.apps.filter(a=>a.status==='Available'&&(!a.ownerOnly||u.role==='Owner')).map(a=>`<label class="check"><input type="checkbox" data-access-user="${u.id}" data-app="${a.id}" ${u.role==='Owner'||u.appIds.includes(a.id)?'checked':''} ${u.role==='Owner'?'disabled':''}>${a.name}</label>`).join('')}</div><button class="secondary" data-action="edit-user" data-id="${u.id}">Manage</button></article>`).join('')}</section>`;}
function bindForms(){if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();submit(e.target,async()=>{await api('auth/profile','PATCH',Object.fromEntries(new FormData(e.target)));await load();notice('Profile saved');});};if($('#password-form'))$('#password-form').onsubmit=e=>{e.preventDefault();submit(e.target,async()=>{await api('auth/password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();notice('Password updated');});};}
function userForm(id){const u=state.team.find(x=>x.id===id)||{};const modal=$('#platform-dialog');modal.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${id?'Manage member':'Add a team member'}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">×</button></div><form id="user-form"><label>Name<input name="name" required value="${escapeHtml(u.name)}"></label><label>Email<input name="email" type="email" required value="${escapeHtml(u.email)}"></label><label>Role<select name="role" aria-label="Role">${['Advocate','Clerk','Owner'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label>${id?'New password (optional)':'Initial password'}<input name="password" type="password" minlength="12" maxlength="128" ${id?'':'required'} autocomplete="new-password"></label>${id?`<label class="check"><input type="checkbox" name="active" ${u.active?'checked':''}>Account active</label>`:`<label class="check"><input type="checkbox" name="advocate" checked>Chambers access</label>`}<p class="error" role="alert"></p><button type="submit" class="primary wide">Save member</button></form>`;if(authStatus.authMethod==='access'){modal.querySelector('input[name=password]').closest('label').remove();modal.querySelector('form').insertAdjacentHTML('beforeend','<p class="hint">Allow this email in Cloudflare Access before sign-in.</p>');}modal.showModal();$('#user-form').onsubmit=e=>{e.preventDefault();submit(e.target,async()=>{const input=Object.fromEntries(new FormData(e.target));if(id)input.active=input.active==='on';else input.appIds=input.advocate==='on'?['advocate']:[];delete input.advocate;await api('users'+(id?'/'+id:''),id?'PATCH':'POST',input);modal.close();await load();notice('Team member saved');});};}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-section],[data-category],[data-action]');if(!target)return;try{if(target.dataset.section){section=target.dataset.section;category='All';query='';render();scrollTo(0,0);return;}if(target.dataset.category){category=target.dataset.category;$('#content').innerHTML=content();return;}const {action,id}=target.dataset;if(action==='launch'){target.disabled=true;try{const result=await api('platform/apps/'+id+'/launch','POST',{});location.assign(id==='daily-spark'?'/take-a-break':state.apps.find(a=>a.id===id)?.studioLegacy?'/moment-studio':result.path);}finally{target.disabled=false;}}if(action==='favorite'){const favorites=state.preferences.favorites.includes(id)?state.preferences.favorites.filter(x=>x!==id):[...state.preferences.favorites,id];await api('platform/preferences','PATCH',{favorites});await load();}if(action==='logout'){const signedOut=await api('auth/logout','POST');if(signedOut.redirect==='/cdn-cgi/access/logout'){location.assign(signedOut.redirect);return;}state=null;section='apps';category='All';query='';await boot();}if(action==='add-user')userForm();if(action==='edit-user')userForm(id);if(action==='close')$('#platform-dialog').close();}catch(err){notice(err.message);}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-theme]')){setTheme(e.target.value);document.querySelectorAll('[data-theme]').forEach(el=>el.value=theme);}if(e.target.dataset.accessUser){const u=state.team.find(x=>x.id===e.target.dataset.accessUser),appId=e.target.dataset.app,ids=e.target.checked?[...u.appIds,appId]:u.appIds.filter(id=>id!==appId);try{await api('platform/access/'+u.id,'PATCH',{appIds:ids});await load();notice('App access updated');}catch(err){e.target.checked=!e.target.checked;notice(err.message);}}});
function publicHome(){queueMicrotask(()=>{if(authStatus?.fullApps||(!authStatus?.freeWorkspace&&authStatus?.authMethod!=='access'))return;document.querySelectorAll('.workspace-card').forEach(card=>{const link=card.querySelector('.workspace-launch');if(link&&!link.getAttribute('href').includes('next=advocate')){card.querySelector('.access-label').textContent='Unavailable in this free version';link.removeAttribute('href');link.textContent='Unavailable';}});});if($('#platform>.public-home'))return;
  $('#platform').innerHTML=`<div class="public-home"><header class="public-topbar synapse-header"><a class="brand" href="/" aria-label="Sushant Synapse home"><img src="/logo-adaptive-192.png" alt="" width="42" height="42"><span>Sushant Synapse<small>PLATFORM</small></span></a><div class="header-actions">${themeControl()}<a class="secondary" href="/signin">Sign in</a></div></header><main id="main"><section class="public-hero home-welcome" aria-labelledby="home-welcome-title"><div class="home-welcome-copy"><span class="eyebrow">A LITTLE MORE POSSIBLE</span><h1 id="home-welcome-title"><span>Small tools.</span> <em>Better everyday.</em></h1><p>Create something thoughtful, clear a task, or take a little break.</p><nav class="home-paths" aria-label="Choose your access"><a class="primary" href="#free-apps">Explore free apps <span aria-hidden="true">↘</span></a><a class="secondary" href="#workspace-apps">Apps requiring sign-in</a><a class="secondary" href="/showcase">Watch demos</a><a class="secondary" href="/support">Support us</a></nav></div><svg class="home-welcome-art" viewBox="0 0 320 210" fill="none" aria-hidden="true" focusable="false"><ellipse cx="160" cy="186" rx="127" ry="13" class="art-shadow"/><g class="art-create" transform="rotate(-12 85 105)"><rect x="27" y="33" width="110" height="145" rx="18" class="art-paper"/><rect x="42" y="49" width="80" height="112" rx="9" class="art-outline"/><path d="M58 75h48M58 89h34M58 103h41" class="art-lines"/><circle cx="82" cy="130" r="15" class="art-accent"/><path d="m76 142-4 20 11-5 11 5-5-20" class="art-ribbon"/></g><g class="art-play" transform="rotate(9 215 98)"><rect x="161" y="23" width="121" height="125" rx="24" class="art-soft"/><circle cx="222" cy="85" r="44" class="art-paper"/><path d="M222 42v86M179 85h86M192 54l60 62M192 116l60-62" class="art-lines"/><circle cx="222" cy="85" r="13" class="art-accent"/><path d="m215 34 7 13 7-13" class="art-ribbon"/></g><g class="art-do" transform="rotate(-3 205 164)"><rect x="124" y="141" width="171" height="46" rx="16" class="art-paper"/><circle cx="148" cy="164" r="10" class="art-accent"/><path d="m143 164 4 4 7-9" class="art-check"/><path d="M170 160h67M170 169h44" class="art-lines"/></g><path d="m140 23 3 9 9 3-9 3-3 9-3-9-9-3 9-3ZM296 104l3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" class="art-accent"/></svg></section><section class="home-daily" aria-labelledby="home-daily-title"><div class="home-daily-mark" aria-hidden="true">24<span>+ − × ÷</span></div><div class="home-daily-copy"><span class="eyebrow">TRY SOMETHING TODAY</span><h2 id="home-daily-title">Four numbers. One little challenge.</h2><p>Use every number once to make 24. A fresh puzzle daily, no sign-in.</p></div><a class="home-daily-play" href="/take-a-break?game=24">Play now <span aria-hidden="true">↗</span></a></section><section id="free-apps" aria-labelledby="free-title"><div class="access-heading"><span class="eyebrow">OPEN TO EVERYONE</span><h2 id="free-title">Free to try. No sign-in.</h2><p>Explore these tools without an account. Focus tasks save in this browser.</p></div><div class="public-apps"><a class="public-app" href="/confessions" aria-label="Open Confessions"><div class="public-app-head"><span class="public-app-category">PLAY / UNTOLD THOUGHTS</span><span class="public-app-arrow">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160"><use href="/home-art.svg?v=20261016-chaos#confessions"></use></svg></div><div class="public-app-copy"><span class="access-label">No name or sign-in requested</span><h2>Confessions</h2><p>A shared confession chat. Leave a thought for everyone and scratch to uncover theirs.</p><div class="public-tags"><span>Scratch to reveal</span><span>Shared stream</span></div><span class="public-launch">Open the confession box ↗</span></div></a><a class="public-app" href="/qr-maker" aria-label="Open QR Maker"><div class="public-app-head"><span class="public-app-category">FREE / EVERYDAY TOOLS</span><span class="public-app-arrow" aria-hidden="true">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160"><use href="/home-art.svg?v=20261016-chaos#qr"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>QR Maker</h2><p>Turn a link or text into a downloadable QR code.</p><span class="public-launch">Create a QR ↗</span></div></a><a class="public-app" href="/photo-resize" aria-label="Open Photo Resize"><div class="public-app-head"><span class="public-app-category">FREE / EVERYDAY TOOLS</span><span class="public-app-arrow" aria-hidden="true">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160"><use href="/home-art.svg?v=20261016-chaos#photo"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Photo Resize</h2><p>Resize and compress photos to a target file size, on your device.</p><span class="public-launch">Resize a photo ↗</span></div></a><a class="public-app" href="/bill-splitter" aria-label="Open Bill Splitter"><div class="public-app-head"><span class="public-app-category">FREE / EVERYDAY TOOLS</span><span class="public-app-arrow" aria-hidden="true">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160"><use href="/home-art.svg#fees"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Bill Splitter</h2><p>Split a bill or trip expenses by amounts, percentages or shares. Copy who owes whom.</p><span class="public-launch">Split a bill ↗</span></div></a><a class="public-app" href="/moment-studio" aria-label="Moment Studio"><div class="public-app-head"><span class="public-app-category">CREATE / CARDS &amp; CERTIFICATES</span><span class="public-app-arrow">&#8599;</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#cards"></use></svg></div><div class="public-app-copy"><span class="access-label">Free &middot; No sign-in required</span><h2>Moment Studio</h2><p>One home for appreciation certificates, greetings, invitations and thoughtful condolences in English or Hindi.</p><div class="public-tags"><span>Cards &amp; awards</span><span>Condolence wording</span></div><span class="public-launch">Create your moment &#8599;</span></div></a><a class="public-app" href="/take-a-break" aria-label="Take a Break"><div class="public-app-head"><span class="public-app-category">PLAY / YOUR BREAK COLLECTION</span><span class="public-app-arrow">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#pause"></use></svg></div><div class="public-app-copy"><span class="access-label">Free · No sign-in required</span><h2>Take a Break</h2><p>Make 24, Crack the Code, Memory Minute, Lights Out and Face-Off. Your familiar Decision Wheel and Pocket Pause are here too.</p><div class="public-tags"><span>Seven activities</span><span>Daily &amp; practice</span></div><span class="public-launch">Find your little break ↗</span></div></a><a class="public-app" href="/decision-wheel" aria-label="Decision Wheel"><div class="public-app-head"><span class="public-app-category">CHOOSE / RANDOM PICKER</span><span class="public-app-arrow">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#wheel"></use></svg></div><div class="public-app-copy"><span class="access-label">Free · No sign-in required</span><h2>Decision Wheel</h2><p>Add your choices and spin the wheel. Pick a winner, remove previous winners and share the result.</p><div class="public-tags"><span>Random picker</span><span>Share results</span></div><span class="public-launch">Open Decision Wheel ↗</span></div></a><a class="public-app news-app" href="/news" aria-label="Open News"><div class="public-app-head"><span class="app-icon green"><svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5C8 2 5 3 3 4v16c3-2 6-1 9 1 3-2 6-3 9-1V4c-3-2-6-1-9 1zm0 0v16"/></svg></span><span class="public-app-category">NEWS / DAILY EDITION</span><span class="public-app-arrow"><svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#news"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>News</h2><p>News and fictional satire by Aakanksha. Prepare the daily newspaper once, then share the same edition with everyone.</p><div class="public-tags"><span>Daily newspaper</span><span>Saved editions</span></div><span class="public-launch">Open News <svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></span></div></a><a class="public-app timetable-app" href="/timetable-lite" aria-label="Timetable Lite"><div class="public-app-head"><span class="public-app-category">EDUCATION / WEEKLY PLANNING</span><span class="public-app-arrow">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#calendar"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Timetable Lite</h2><p>Create conflict-free weekly timetables for your school or coaching institute. Simple, private and ready to print.</p><div class="public-tags"><span>Automatic scheduling</span><span>PDF &amp; image</span></div><span class="public-launch">Plan your week ↗</span></div></a><a class="public-app" href="/ritual-assist" aria-label="Ritual Assist"><div class="public-app-head"><span class="public-app-category">TRADITIONS / HINDU PREPARATION</span><span class="public-app-arrow">↗</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#ritual"></use></svg></div><div class="public-app-copy"><span class="access-label">Free · No sign-in required</span><h2>Ritual Assist</h2><p>Hindu Shubh and Ashubh preparation in English and Hindi. Explore steps, arrange puja materials and keep a checklist.</p><div class="public-tags"><span>15 ritual guides</span><span>Steps &amp; items</span></div><span class="public-launch">Prepare with care ↗</span></div></a><a class="public-app" href="/team-mixer" aria-label="Team Mixer"><div class="public-app-head"><span class="public-app-category">GROUPS / RANDOM TEAMS</span><span class="public-app-arrow">&#8599;</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#teams"></use></svg></div><div class="public-app-copy"><span class="access-label">Free &middot; No sign-in required</span><h2>Team Mixer</h2><p>Enter names and reveal a fresh set of teams. Balanced sizes, random assignments and a team card to share.</p><div class="public-tags"><span>Random teams</span><span>Download &amp; share</span></div><span class="public-launch">Mix your teams &#8599;</span></div></a><a class="public-app" href="/focus" aria-label="Open Focus"><div class="public-app-head"><span class="public-app-category">WORK / FOCUS</span><span class="public-app-arrow" aria-hidden="true">&rarr;</span></div><div class="news-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160"><use href="/home-art.svg#calendar"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Focus</h2><p>Plan today, pick one task and work without rushing. Browser-saved daily tasks, priorities, time estimates and an adjustable focus timer.</p><div class="public-tags"><span>Daily tasks</span><span>Focus timer</span></div><span class="public-launch">Open Focus &rarr;</span></div></a><a class="public-app fund-app" href="/fund-overlap" aria-label="Fund Lens"><div class="public-app-head"><span class="app-icon blue"><svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="10" r="6"/><circle cx="15" cy="10" r="6"/><path d="M12 16v5m-4 0h8"/></svg></span><span class="public-app-category">INVESTING / FUND LENS</span><span class="public-app-arrow"><svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></span></div><div class="fund-visual" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#lens"></use></svg></div><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Fund Lens</h2><p>Uncover shared holdings, compare industries and see what each fund adds to the mix.</p><div class="public-tags"><span>Holdings overlap</span><span>What-if comparisons</span></div><span class="public-launch">Open Fund Lens <svg viewBox="0 0 24 24" class="icon" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></span></div></a><a class="public-app news-app" href="/satire-arena" aria-label="Open Satire Arena"><div class="public-app-head"><span class="public-app-category">PLAY / POLITICAL PARODY</span><span class="public-app-arrow">↗</span></div><img class="arena-home-art" src="/satire-arena/cartoon-cast.png" alt="Three fictional political cartoon characters" loading="lazy"><div class="public-app-copy"><span class="access-label">No sign-in required</span><h2>Garland<br>or roast?</h2><p>Meet the cartoon cast. Choose from six reactions, including Garland, Applause, Tomato and Just laughing and watch shared Fans vs Critics scores. New round at midnight IST.</p><div class="public-tags"><span>Daily reactions</span><span>Shared cloud scores</span></div><span class="public-launch">Open Satire Arena ↗</span></div></a></div></section><aside class="synapse-sponsor" data-sponsor-slot="home" aria-label="Sponsorship opportunity"><div class="synapse-sponsor-heading"><span class="synapse-sponsor-label">Sponsorship opportunity</span></div><div class="synapse-sponsor-body"><div class="synapse-sponsor-copy"><h2 class="synapse-sponsor-title">A little space for a thoughtful brand.</h2><p class="synapse-sponsor-description">Introduce your business through one quiet, clearly labelled placement.</p></div><a class="synapse-sponsor-link" href="/sponsor">Explore sponsorship</a></div></aside><section class="arena-discovery" aria-labelledby="arena-discovery-title"><h2 id="arena-discovery-title">Daily Satire · Satire Arena</h2><svg width="120" height="100" viewBox="0 0 180 160" aria-hidden="true"><use href="/home-art.svg#satire"></use></svg><p>Big entrances. Small punchlines. Fictional characters, six reactions and genuine daily results.</p><p data-home-satire>Enjoy the parody Arena and discover original jokes from the editorial desk.</p><nav aria-label="Explore Sushant Synapse"><a href="#free-apps">Free Tools</a> · <a href="/take-a-break">Quick Games</a> · <a href="/satire-arena/daily">Daily Satire</a> · <a href="/satire-arena">Enter the Arena</a></nav></section><section id="workspace-apps" aria-labelledby="workspace-title"><div class="access-heading"><span class="eyebrow">YOUR PRIVATE WORKSPACE</span><h2 id="workspace-title">Sign in to work.</h2><p>Use an existing platform account. App access is managed by your platform owner.</p></div><div class="workspace-grid"><article class="workspace-card"><div class="workspace-card-art" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" focusable="false"><use href="/home-art.svg#community"></use></svg><span class="workspace-lock"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></svg></span></div><div class="workspace-card-copy"><span class="access-label private">Sign-in + Samaj role</span><h3>DIGITAL SAMAJ</h3><p>Register families, connect generations and communicate with verified community members.</p><a class="secondary workspace-launch" href="/signin?next=digital-samaj">Sign in to DIGITAL SAMAJ →</a></div></article><article class="workspace-card"><div class="workspace-card-art" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" focusable="false"><use href="/home-art.svg#chambers"></use></svg><span class="workspace-lock"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></svg></span></div><div class="workspace-card-copy"><span class="access-label private">Sign-in + app access</span><h3>Chambers</h3><p>Cases, clients, hearings and fees in your chambers workspace.</p><a class="secondary workspace-launch" href="/signin?next=advocate">Sign in to Chambers →</a></div></article><article class="workspace-card"><div class="workspace-card-art" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" focusable="false"><use href="/home-art.svg#trophy"></use></svg><span class="workspace-lock"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></svg></span></div><div class="workspace-card-copy"><span class="access-label private">Sign-in + app access</span><h3>Tournament Lite</h3><p>Create fixtures, record scores and manage tournaments with assigned app access.</p><p class="viewer-note">Viewing results? Open the organizer’s shared results link. No account needed.</p><a class="secondary workspace-launch" href="/signin?next=tournament-lite">Sign in to Tournament Lite →</a></div></article><article class="workspace-card"><div class="workspace-card-art" aria-hidden="true"><svg class="home-sculpture" viewBox="0 0 180 160" focusable="false"><use href="/home-art.svg#fees"></use></svg><span class="workspace-lock"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></svg></span></div><div class="workspace-card-copy"><span class="access-label private">Owner account only</span><h3>BatchFee Lite</h3><p>Manage academy students, fees and receipts in a private workspace for the platform owner.</p><a class="secondary workspace-launch" href="/signin?next=batchfee-lite">Sign in to BatchFee Lite →</a></div></article></div></section><footer><span>Sushant Synapse Platform</span><span><a href="/showcase">Watch demos</a> · <a href="/support">Support us</a> · <a href="/sponsor">Sponsorship</a></span></footer></main></div>`;
}
async function boot(){const first=!boot.started;boot.started=true;authStatus=await(first?(window.synapseInitialAuthStatus??=api('auth/status')):api('auth/status'));window.dispatchEvent(new CustomEvent('synapse-auth-change',{detail:{user:authStatus.user||null}}));if(authStatus.user){const target=requestedApp();if(target){location.assign(target.path);return;}await load();}else if(location.pathname==='/signin'||new URLSearchParams(location.search).get('next')==='advocate')authView();else publicHome();}
boot().catch(e=>{if(location.pathname==='/'){publicHome();if(window.SynapseAvailability)SynapseAvailability.show();else $('#main').insertAdjacentHTML('afterbegin','<p role="status">The backend is currently unavailable. Fund Lens, News temporary editions, Ritual Assist, Moment Studio, Timetable Lite, Daily Spark, Decision Wheel, Team Mixer and Pocket Pause remain available with an internet connection. Chambers, DIGITAL SAMAJ, Tournament Lite, BatchFee Lite and News saved editions need the server connection to return.</p>');}else $('#platform').innerHTML=`<main id="main" class="loading"><h1>Sign-in is temporarily unavailable</h1><p>The backend is currently unavailable. Please try again later.</p><a href="" class="secondary">Try again</a><a href="/" class="secondary">Back to all apps</a></main>`;});

function freeAuthView(){
 $('#platform').innerHTML=`<main id="main" class="auth-layout"><section class="welcome">${brand()}<div class="welcome-copy"><h1>Your work.<br>In good order.</h1><p>Chambers uses a code sent to your approved email address.</p></div></section><section class="auth-panel"><div class="auth-theme">${themeControl()}</div><h2>Sign in with your email</h2><p>Your workspace owner controls access. Documents and larger workflows are unavailable in this free cloud version.</p><a class="primary wide" href="/access-login">Continue to email-code sign-in</a><p class="auth-note">If access is denied, ask your workspace owner to approve your email.</p><a href="/">Back to all apps</a></section></main>`;
}
function freeProfileView(){return `<div class="settings-grid"><section class="panel"><h2>Your profile</h2><form id="profile-form"><label>Name<input name="name" value="${escapeHtml(state.user.name)}" required maxlength="120"></label><label>Email<input name="email" type="email" value="${escapeHtml(state.user.email)}" readonly required></label><p class="error" role="alert"></p><button type="submit" class="primary">Save profile</button></form></section><section class="panel"><h2>Sign-in and security</h2><p>Sign-in uses a code sent to your approved email address. Contact the owner for an email or access change.</p><button class="secondary signout" data-action="logout">Sign out</button></section><section class="panel"><h2>Appearance</h2>${themeControl()}</section></div>`;}
